def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    pts_all = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    cr = sum(r for r, c in pts_all) / len(pts_all)
    cc = sum(c for r, c in pts_all) / len(pts_all)

    for color in set(v for row in grid for v in row if v != bg):
        pts = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == color}
        for dr in (-1, 1):
            for dc in (-1, 1):
                # Find contiguous diagonal segments; extend outward from the
                # endpoint farther from the overall figure's center.
                for r, c in list(pts):
                    if (r-dr, c-dc) in pts:
                        continue
                    seg = []
                    rr, cc2 = r, c
                    while (rr, cc2) in pts:
                        seg.append((rr, cc2))
                        rr += dr
                        cc2 += dc
                    if len(seg) < 2:
                        continue
                    a, b = seg[0], seg[-1]
                    da = (a[0]-cr)**2 + (a[1]-cc)**2
                    db = (b[0]-cr)**2 + (b[1]-cc)**2
                    # Extend from the segment endpoint pointing away from center.
                    if da > db:
                        rr, cc2 = a[0]-dr, a[1]-dc
                        sr, sc = -dr, -dc
                    else:
                        rr, cc2 = b[0]+dr, b[1]+dc
                        sr, sc = dr, dc
                    while 0 <= rr < h and 0 <= cc2 < w:
                        if out[rr][cc2] == bg:
                            out[rr][cc2] = color
                        rr += sr
                        cc2 += sc
    return out
